package checks;
import com.raiiiden.warborn.hybrid.*;import com.raiiiden.warborn.common.util.*;import com.raiiiden.warborn.common.item.*;import net.minecraft.world.item.*;import net.minecraft.server.level.*;import net.minecraft.client.*;import com.mojang.blaze3d.vertex.*;import java.lang.reflect.*;
public class TacticalChecks{
 static int n;static void ok(boolean v,String s){n++;if(!v)throw new AssertionError(s);}static void resetSound()throws Exception{Field f=Tactical7.class.getDeclaredField("lastSound");f.setAccessible(true);f.setLong(null,0);}
 public static class Mesh extends HybridChecks.Consumer{public int vertices,cyan,dark;public float zmin=100,zmax=-100,ymin=100;public VertexConsumer addVertex(float x,float y,float z){vertices++;zmin=Math.min(zmin,z);zmax=Math.max(zmax,z);ymin=Math.min(ymin,y);return this;}public VertexConsumer setUv(float u,float v){if(v>.5f){if(u>.5f)cyan++;else dark++;}return this;}}
 public static void main(String[]a)throws Exception{
  Mesh on=new Mesh();Tactical7.draw(new PoseStack(),on,0,true,true);ok(on.vertices==256,"bridge + mount + four separate tubes/rims/glass");ok(on.cyan==16&&on.dark==0,"four powered cyan glass fronts");Mesh off=new Mesh();Tactical7.draw(new PoseStack(),off,0,true,false);ok(off.dark==16&&off.cyan==0,"four dark unpowered glass fronts");Mesh up=new Mesh();Tactical7.draw(new PoseStack(),up,0,false,false);ok(up.ymin<off.ymin&&up.zmin>off.zmin,"raised optical tubes pivot above the forehead");
  Minecraft mc=Minecraft.getInstance();mc.level=new Object();mc.player=new ServerPlayer();ServerPlayer p=mc.player;WBArmorItem item=new WBArmorItem();p.helmet=NvgChecks.helmet(item,"thermal_hybrid",50000);NvgLink2.wear(p);Tactical7.tick();ok(mc.sounds.played==0,"equipping does not auto play activation");ok(Tactical7.hybrid(p.helmet),"native hybrid identification");NvgChecks.lowered(p);resetSound();Tactical7.tick();ok(mc.sounds.played==1,"one activation sound on lowering");for(int i=0;i<200;i++)Tactical7.tick();ok(mc.sounds.played==1,"no per-tick sound spam");item.setTopOpen(p.helmet,true);resetSound();Tactical7.tick();ok(mc.sounds.played==2,"one deactivation sound on raising");p.helmet=NvgChecks.helmet(item,"thermal_hybrid",0);NvgChecks.lowered(p);resetSound();Tactical7.tick();ok(mc.sounds.played==2,"flat battery cannot activate optics or sound");mc.player=null;Tactical7.tick();mc.player=new ServerPlayer();mc.player.helmet=NvgChecks.helmet(item,"thermal_hybrid",50000);NvgChecks.lowered(mc.player);resetSound();Tactical7.tick();ok(mc.sounds.played==2,"reconnect does not fabricate a transition");
  System.out.println("TACTICAL_FOUR_LENSES_VISOR_SOUND_CHECKS="+n);
 }
}
